INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT523','SV3','旧护照签证页剪角，咨询新旧护照联用规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V523','SIT523','P1','twist','ban_chinh_thuc',NULL,'旧护照到期剪角，居留贴纸短期可新旧护照联用，缓冲期三十天，超时无法正常出入境，必须转移居留许可至新护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_01','V523','阮明',1,'警官您好，我的旧护照到期被剪角作废了，但是有效的居留贴纸还贴在旧护照上，这个要怎么处理？','jǐng guān nín hǎo ， wǒ de jiù hù zhào dào qī bèi jiǎn jiǎo zuò fèi le ， dàn shì yǒu xiào de jū liú tiē zhǐ hái tiē zài jiù hù zhào shàng ， zhè ge yào zěn me chǔ lǐ ？','Chào anh công an, hộ chiếu cũ của em hết hạn nên bị cắt góc hủy rồi, nhưng tem cư trú còn hiệu lực lại đang dán trên hộ chiếu cũ, vậy phải xử lý thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_02','V523','辅警',2,'这种情况可以新旧两本护照一起带着，出示给海关查验，短期是可以正常出入境的。','zhè zhǒng qíng kuàng kě yǐ xīn jiù liǎng běn hù zhào yì qǐ dài zhe ， chū shì gěi hǎi guān chá yàn ， duǎn qī shì kě yǐ zhèng cháng chū rù jìng de 。','Trường hợp này thì mang cả hai hộ chiếu cũ và mới theo bên mình, xuất trình cho hải quan kiểm tra, trong thời gian ngắn thì vẫn xuất nhập cảnh bình thường được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_03','V523','阮明',3,'那能一直这样用吗？还是有时间限制？','nà néng yì zhí zhè yàng yòng ma ？ hái shì yǒu shí jiān xiàn zhì ？','Vậy dùng như thế mãi được không ạ, hay là có giới hạn thời gian?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_04','V523','辅警',4,'不能长期联用的，只有三十天的缓冲期，超期之后就无效了，必须把居留信息转移到新护照上。','bù néng cháng qī lián yòng de ， zhǐ yǒu sān shí tiān de huǎn chōng qī ， chāo qī zhī hòu jiù wú xiào le ， bì xū bǎ jū liú xìn xī zhuǎn yí dào xīn hù zhào shàng 。','Không dùng chung lâu dài được đâu, chỉ có thời gian đệm ba mươi ngày thôi, quá hạn là không còn hiệu lực nữa, bắt buộc phải chuyển thông tin cư trú sang hộ chiếu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_05','V523','阮明',5,'啊，只有三十天？那转移居留要怎么办理？是单独预约，还是等续签的时候一起弄？','a ， zhǐ yǒu sān shí tiān ？ nà zhuǎn yí jū liú yào zěn me bàn lǐ ？ shì dān dú yù yuē ， hái shì děng xù qiān de shí hòu yì qǐ nòng ？','Ơ, chỉ có ba mươi ngày thôi ạ? Vậy chuyển cư trú thì làm thủ tục thế nào? Phải đặt lịch hẹn riêng hay đợi lúc gia hạn visa làm luôn một thể ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_06','V523','辅警',6,'需要单独预约居留信息变更业务，不用等到签证到期，尽早办理更稳妥。','xū yào dān dú yù yuē jū liú xìn xī biàn gēng yè wù ， bù yòng děng dào qiān zhèng dào qī ， jǐn zǎo bàn lǐ gèng wěn tuǒ 。','Phải đặt lịch hẹn riêng cho việc thay đổi thông tin cư trú, không cần đợi đến khi visa hết hạn đâu, làm sớm cho chắc ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_07','V523','阮明',7,'好的，那我这三天内就预约窗口，把居留贴纸转移到新护照上。','hǎo de ， nà wǒ zhè sān tiān nèi jiù yù yuē chuāng kǒu ， bǎ jū liú tiē zhǐ zhuǎn yí dào xīn hù zhào shàng 。','Vâng ạ, vậy trong ba ngày tới em sẽ đặt lịch ra quầy, chuyển tem cư trú sang hộ chiếu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT524','SV4','校内转专业，办理居留许可信息变更',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V524','SIT524','P1','suon_se','ban_chinh_thuc',NULL,'留学生校内转专业、更换学院，必须三十日内到出入境更新居留证件信息，信息不符会被判定证件失效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_01','V524','阮明',1,'您好，我这学期在校内转了专业，想来办理居留证件的信息变更。','nín hǎo ， wǒ zhè xué qī zài xiào nèi zhuǎn le zhuān yè ， xiǎng lái bàn lǐ jū liú zhèng jiàn de xìn xī biàn gēng 。','Chào chị, học kỳ này em chuyển ngành học trong trường, em muốn đến làm thủ tục thay đổi thông tin trên giấy tờ cư trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_02','V524','工作人员',2,'可以的，请提交你的专业调整证明、个人护照，还有一张白底证件照。','kě yǐ de ， qǐng tí jiāo nǐ de zhuān yè tiáo zhěng zhèng míng 、 gè rén hù zhào ， hái yǒu yī zhāng bái dǐ zhèng jiàn zhào 。','Được chứ, em nộp giấy xác nhận chuyển ngành, hộ chiếu cá nhân, và một tấm ảnh thẻ nền trắng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_03','V524','阮明',3,'好的。我想问一下，只是变更就读专业，签证的到期时间会跟着延后吗？','hǎo de 。 wǒ xiǎng wèn yī xià ， zhǐ shì biàn gēng jiù dú zhuān yè ， qiān zhèng de dào qī shí jiān huì gēn zhe yán hòu ma ？','Vâng ạ. Em muốn hỏi thêm, nếu chỉ thay đổi ngành học thôi thì thời hạn visa có bị dời theo không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_04','V524','工作人员',4,'不会的，居留有效期保持不变，只会更新你证件上的就读专业信息。','bú huì de ， jū liú yǒu xiào qī bǎo chí bù biàn ， zhǐ huì gēng xīn nǐ zhèng jiàn shàng de jiù dú zhuān yè xìn xī 。','Không đâu, thời hạn cư trú vẫn giữ nguyên, chỉ cập nhật lại thông tin ngành học trên giấy tờ của em thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_05','V524','阮明',5,'了解了。那这个变更业务要办多久？当天能拿到新证件吗？','liǎo jiě le 。 nà zhè ge biàn gēng yè wù yào bàn duō jiǔ ？ dàng tiān néng ná dào xīn zhèng jiàn ma ？','Em hiểu rồi ạ. Vậy thủ tục thay đổi này mất bao lâu ạ? Trong ngày có lấy được giấy mới không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_06','V524','工作人员',6,'办理时长是三个工作日，没办法当场取证，需要后续来领取。','bàn lǐ shí cháng shì sān gè gōng zuò rì ， méi bàn fǎ dāng chǎng qǔ zhèng ， xū yào hòu xù lái lǐng qǔ 。','Thời gian xử lý là ba ngày làm việc, không lấy ngay được đâu, phải quay lại lấy sau nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_07','V524','阮明',7,'那费用方面呢？信息变更需要交手续费或者工本费吗？','nà fèi yòng fāng miàn ne ？ xìn xī biàn gēng xū yào jiāo shǒu xù fèi huò zhě gōng běn fèi ma ？','Vậy còn về chi phí thì sao ạ? Thay đổi thông tin có phải đóng phí thủ tục hay lệ phí làm giấy tờ không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_08','V524','工作人员',8,'校内转专业的信息变更属于免费业务，没有任何额外费用。','xiào nèi zhuǎn zhuān yè de xìn xī biàn gēng shǔ yú miǎn fèi yè wù ， méi yǒu rèn hé é wài fèi yòng 。','Thay đổi thông tin do chuyển ngành trong trường thì miễn phí, không phát sinh thêm khoản nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_09','V524','阮明',9,'太好了，我材料都准备好了，麻烦您帮我受理一下。','tài hǎo le ， wǒ cái liào dōu zhǔn bèi hǎo le ， má fán nín bāng wǒ shòu lǐ yī xià 。','Tuyệt quá, hồ sơ của em chuẩn bị đầy đủ hết rồi, phiền chị tiếp nhận giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT525','SV4','从A校转学至另一城市高校，办理居留迁出迁入',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V525','SIT525','P1','twist','chinh_thuc',NULL,'跨城市转学居留无法异地转移，原城市居留注销失效，抵达新城市三十日内必须重新申请本地学生居留许可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_01','V525','阮明',1,'老师您好，我近期要转学去外地的高校，想咨询一下居留迁出的办理流程。','lǎo shī nín hǎo ， wǒ jìn qī yào zhuǎn xué qù wài dì de gāo xiào ， xiǎng zī xún yī xià jū liú qiān chū de bàn lǐ liú chéng 。','Chào thầy, gần đây em sắp chuyển trường sang một trường ở tỉnh khác, em muốn hỏi quy trình làm thủ tục chuyển đi cư trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_02','V525','老师',2,'首先要在学校开好转学离校证明，然后带着证明去本地出入境大厅办理居留迁出备案。','shǒu xiān yào zài xué xiào kāi hǎo zhuǎn xué lí xiào zhèng míng ， rán hòu dài zhe zhèng míng qù běn dì chū rù jìng dà tīng bàn lǐ jū liú qiān chū bèi àn 。','Trước tiên em cần xin giấy xác nhận thôi học chuyển trường từ trường, sau đó mang giấy này ra sảnh xuất nhập cảnh địa phương để làm thủ tục đăng ký chuyển đi cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_03','V525','阮明',3,'那我办完迁出之后，原来的居留还能用吗？','nà wǒ bàn wán qiān chū zhī hòu ， yuán lái de jū liú hái néng yòng ma ？','Vậy làm thủ tục chuyển đi xong rồi, cư trú cũ của em còn dùng được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_04','V525','老师',4,'不行的，迁出手续办理完成的当天，你原本的居留许可就自动失效了。','bù xíng de ， qiān chū shǒu xù bàn lǐ wán chéng dí dàng tiān ， nǐ yuán běn de jū liú xǔ kě jiù zì dòng shī xiào le 。','Không được đâu, ngay trong ngày hoàn tất thủ tục chuyển đi, giấy phép cư trú cũ của em sẽ tự động hết hiệu lực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_05','V525','阮明',5,'这样啊……那我中间跨城市转学出行，没有有效居留会不会有问题？','zhè yàng a …… nà wǒ zhōng jiān kuà chéng shì zhuǎn xué chū xíng ， méi yǒu yǒu xiào jū liú huì bú huì yǒu wèn tí ？','Vậy à... thế trong lúc em di chuyển giữa các tỉnh để chuyển trường mà không có cư trú hợp lệ thì có vấn đề gì không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_06','V525','老师',6,'不用担心，出入境会给你开具三十天的临时停留证明，专门用来中转过渡。','bù yòng dān xīn ， chū rù jìng huì gěi nǐ kāi jù sān shí tiān de lín shí tíng liú zhèng míng ， zhuān mén yòng lái zhōng zhuǎn guò dù 。','Không cần lo, bên xuất nhập cảnh sẽ cấp cho em giấy tạm trú ba mươi ngày, dùng riêng cho giai đoạn chuyển tiếp này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_07','V525','阮明',7,'那我到了新学校之后，是不是要重新提交所有居留材料？','nà wǒ dào le xīn xué xiào zhī hòu ， shì bú shì yào chóng xīn tí jiāo suǒ yǒu jū liú cái liào ？','Vậy khi đến trường mới rồi, em có phải nộp lại toàn bộ hồ sơ cư trú từ đầu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_08','V525','老师',8,'对的，需要按照新生标准，全套重新递交材料，办理新城市的居留许可。','duì de ， xū yào àn zhào xīn shēng biāo zhǔn ， quán tào chóng xīn dì jiāo cái liào ， bàn lǐ xīn chéng shì de jū liú xǔ kě 。','Đúng vậy, em phải làm theo tiêu chuẩn của sinh viên mới, nộp lại toàn bộ hồ sơ để làm giấy phép cư trú ở thành phố mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_09','V525','阮明',9,'我明白了，那我先办好离校转学证明，再去大厅办理迁出备案。','wǒ míng bái le ， nà wǒ xiān bàn hǎo lí xiào zhuǎn xué zhèng míng ， zài qù dà tīng bàn lǐ qiān chū bèi àn 。','Em hiểu rồi ạ, vậy em sẽ xin giấy xác nhận thôi học chuyển trường trước, rồi ra sảnh làm thủ tục đăng ký chuyển đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT526','SV4','更换校外租房地址，10日内办理居留地址变更',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V526','SIT526','P1','that_bai_nhe','tuy_y',NULL,'外籍人员更换居住地址法定十日内向社区更新住宿信息，多次逾期备案会影响后续居留续签审核。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_01','V526','阮明',1,'网格员你好，我最近换了校外的出租房，但是搬家之后太忙了，超过十天没办地址变更登记。','wǎng gé yuán nǐ hǎo ， wǒ zuì jìn huàn le xiào wài de chū zū fáng ， dàn shì bān jiā zhī hòu tài máng le ， chāo guò shí tiān méi bàn dì zhǐ biàn gēng dēng jì 。','Chào anh, gần đây em chuyển ra ngoài thuê trọ, nhưng chuyển nhà xong bận quá nên để quá mười ngày mà chưa đăng ký thay đổi địa chỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_02','V526','网格员',2,'哎呀，这个要注意的，外籍人员更换居住地址，法定要十天内更新备案的，逾期会有警告记录。','āi yā ， zhè ge yào zhù yì de ， wài jí rén yuán gēng huàn jū zhù dì zhǐ ， fǎ dìng yào shí tiān nèi gēng xīn bèi àn de ， yú qī huì yǒu jǐng gào jì lù 。','Ôi, cái này phải chú ý đấy nhé, người nước ngoài thay đổi chỗ ở là theo luật phải cập nhật đăng ký trong vòng mười ngày, để quá hạn là sẽ bị ghi nhận cảnh cáo đó.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_03','V526','阮明',3,'我知道错了，最近上课太忙完全忘了。我现在来补办，会被罚款吗？','wǒ zhī dào cuò le ， zuì jìn shàng kè tài máng wán quán wàng le 。 wǒ xiàn zài lái bǔ bàn ， huì bèi fá kuǎn ma ？','Em biết sai rồi ạ, dạo này đi học bận quá nên quên mất luôn. Giờ em ra làm bù thì có bị phạt tiền không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_04','V526','网格员',4,'你是第一次轻微超期，只做书面警告，不会罚款。但要是下次再逾期，就会有行政处罚了。','nǐ shì dì yī cì qīng wēi chāo qī ， zhǐ zuò shū miàn jǐng gào ， bú huì fá kuǎn 。 dàn yào shì xià cì zài yú qī ， jiù huì yǒu xíng zhèng chǔ fá le 。','Em quá hạn nhẹ lần đầu thì chỉ bị cảnh cáo bằng văn bản thôi, không phạt tiền đâu. Nhưng lần sau mà còn quá hạn nữa là sẽ bị xử phạt hành chính đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_05','V526','阮明',5,'还好只是警告！那补办的话，需要房东过来配合吗？','hái hǎo zhǐ shì jǐng gào ！ nà bǔ bàn de huà ， xū yào fáng dōng guò lái pèi hé ma ？','May quá chỉ bị cảnh cáo thôi! Vậy làm bù thì có cần chủ nhà đến phối hợp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_06','V526','网格员',6,'需要的，得让房东本人到场签字，我们这边才能同步打印新的住宿登记单。','xū yào de ， dé ràng fáng dōng běn rén dào chǎng qiān zì ， wǒ men zhè biān cái néng tóng bù dǎ yìn xīn de zhù sù dēng jì dān 。','Cần chứ, phải để chủ nhà đích thân đến ký tên, bên anh mới in được phiếu đăng ký lưu trú mới đồng bộ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_07','V526','阮明',7,'好，我现在马上联系房东过来，立刻补办变更登记。','hǎo ， wǒ xiàn zài mǎ shàng lián xì fáng dōng guò lái ， lì kè bǔ bàn biàn gēng dēng jì 。','Vâng, em liên hệ chủ nhà đến ngay bây giờ, làm bù đăng ký thay đổi luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT527','SV4','护照个人信息更新，同步更新居留证件信息',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V527','SIT527','P1','suon_se','chinh_thuc',NULL,'护照姓名、国籍、证件编号等核心信息变动后，必须同步更新居留许可，证件信息不一致会被判定无效证件。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_01','V527','阮明',1,'您好，我刚更换了新护照，上面的姓名拼写更新了，想来同步改一下居留卡的对应信息。','nín hǎo ， wǒ gāng gēng huàn le xīn hù zhào ， shàng miàn de xìng míng pīn xiě gēng xīn le ， xiǎng lái tóng bù gǎi yī xià jū liú kǎ de duì yìng xìn xī 。','Chào chị, em vừa đổi hộ chiếu mới, cách viết tên trên đó có cập nhật, em muốn đến đồng bộ lại thông tin tương ứng trên thẻ cư trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_02','V527','工作人员',2,'可以办理。请提供你的新护照、使馆开具的信息变更证明，还有一张证件照。','kě yǐ bàn lǐ 。 qǐng tí gōng nǐ de xīn hù zhào 、 shǐ guǎn kāi jù de xìn xī biàn gēng zhèng míng ， hái yǒu yī zhāng zhèng jiàn zhào 。','Được, em cung cấp hộ chiếu mới, giấy xác nhận thay đổi thông tin do đại sứ quán cấp, và một tấm ảnh thẻ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_03','V527','阮明',3,'好的。我想确认一下，信息改完之后，居留的到期时间会不会变？','hǎo de 。 wǒ xiǎng què rèn yī xià ， xìn xī gǎi wán zhī hòu ， jū liú de dào qī shí jiān huì bú huì biàn ？','Vâng ạ. Em muốn xác nhận lại, sau khi sửa thông tin xong thì thời hạn cư trú có thay đổi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_04','V527','工作人员',4,'有效期完全不变，系统只同步更新你的姓名、护照编号这些核心信息。','yǒu xiào qī wán quán bù biàn ， xì tǒng zhǐ tóng bù gēng xīn nǐ de xìng míng 、 hù zhào biān hào zhè xiē hé xīn xìn xī 。','Thời hạn hoàn toàn không đổi, hệ thống chỉ đồng bộ cập nhật những thông tin cốt lõi như tên và số hộ chiếu của em thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_05','V527','阮明',5,'那就没问题。那更新之后，我出入境、坐高铁、住酒店，就不会显示信息不符了吧？','nà jiù méi wèn tí 。 nà gēng xīn zhī hòu ， wǒ chū rù jìng 、 zuò gāo tiě 、 zhù jiǔ diàn ， jiù bú huì xiǎn shì xìn xī bù fú le ba ？','Vậy thì không vấn đề gì rồi. Sau khi cập nhật xong, khi em xuất nhập cảnh, đi tàu cao tốc, hay ở khách sạn thì sẽ không bị báo sai lệch thông tin nữa đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_06','V527','工作人员',6,'对的，信息是实时同步的，全国所有查验终端都会刷新最新数据，不会有异常。','duì de ， xìn xī shì shí shí tóng bù de ， quán guó suǒ yǒu chá yàn zhōng duān dōu huì shuā xīn zuì xīn shù jù ， bú huì yǒu yì cháng 。','Đúng vậy, thông tin được đồng bộ theo thời gian thực, tất cả các điểm kiểm tra trên toàn quốc đều sẽ cập nhật dữ liệu mới nhất, không có gì bất thường đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_07','V527','阮明',7,'嗯，我材料都带齐了，麻烦您帮我受理一下这个变更业务。','ń ， wǒ cái liào dōu dài qí le ， má fán nín bāng wǒ shòu lǐ yī xià zhè ge biàn gēng yè wù 。','Vâng, hồ sơ em mang đủ hết rồi, phiền chị tiếp nhận giúp em thủ tục thay đổi này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT528','SV5','咨询留学生合法校外实习签证备案流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V528','SIT528','P1','twist','ban_chinh_thuc',NULL,'外籍留学生无备案校外实习属于非法务工，一旦查实会行政处罚，严重者不予续签居留许可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_01','V528','阮明',1,'老师，我最近找了一家校外企业的实习，想问问留学生实习要怎么备案？','lǎo shī ， wǒ zuì jìn zhǎo le yī jiā xiào wài qǐ yè de shí xí ， xiǎng wèn wèn liú xué shēng shí xí yào zěn me bèi àn ？','Thầy ơi, gần đây em xin được thực tập ở một công ty ngoài trường, cho em hỏi du học sinh đi thực tập thì phải đăng ký như thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_02','V528','老师',2,'校外实习管控很严格，必须学校、你本人、实习企业三方签协议，完成备案才算合法。','xiào wài shí xí guǎn kòng hěn yán gé ， bì xū xué xiào 、 nǐ běn rén 、 shí xí qǐ yè sān fāng qiān xié yì ， wán chéng bèi àn cái suàn hé fǎ 。','Thực tập ngoài trường quản lý rất chặt, bắt buộc phải có ba bên là trường, bản thân em, và công ty thực tập cùng ký thỏa thuận, hoàn tất đăng ký thì mới hợp pháp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_03','V528','阮明',3,'啊？如果我先去实习，后面再补备案可以吗？会不会影响之后的签证续签？','a ？ rú guǒ wǒ xiān qù shí xí ， hòu miàn zài bǔ bèi àn kě yǐ ma ？ huì bú huì yǐng xiǎng zhī hòu de qiān zhèng xù qiān ？','Ơ? Nếu em đi thực tập trước rồi đăng ký bù sau có được không ạ? Có ảnh hưởng đến việc gia hạn visa sau này không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_04','V528','老师',4,'绝对不行。没有备案的校外务工属于非法就业，一旦查到，不仅会罚款，还会直接缩短你的居留期限。','jué duì bù xíng 。 méi yǒu bèi àn de xiào wài wù gōng shǔ yú fēi fǎ jiù yè ， yí dàn chá dào ， bù jǐn huì fá kuǎn ， hái huì zhí jiē suō duǎn nǐ de jū liú qī xiàn 。','Tuyệt đối không được. Đi làm ngoài trường mà chưa đăng ký là thuộc diện làm việc trái phép, một khi bị phát hiện thì không chỉ bị phạt tiền mà còn bị cắt ngắn thời hạn cư trú của em luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_05','V528','阮明',5,'我明白了。那我还有个问题，要是我备案了一家公司，中途想换实习单位，还能重新备案吗？','wǒ míng bái le 。 nà wǒ hái yǒu gè wèn tí ， yào shì wǒ bèi àn le yī jiā gōng sī ， zhōng tú xiǎng huàn shí xí dān wèi ， hái néng chóng xīn bèi àn ma ？','Em hiểu rồi ạ. Em còn một câu hỏi nữa, nếu em đã đăng ký một công ty rồi, giữa chừng muốn đổi nơi thực tập thì có đăng ký lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_06','V528','老师',6,'不能直接新增，得先把原来的实习备案注销掉，再重新提交新的三方协议才行。','bù néng zhí jiē xīn zēng ， dé xiān bǎ yuán lái de shí xí bèi àn zhù xiāo diào ， zài chóng xīn tí jiāo xīn de sān fāng xié yì cái xíng 。','Không thể thêm trực tiếp được đâu, phải hủy đăng ký thực tập cũ trước, rồi nộp lại thỏa thuận ba bên mới thì mới được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_07','V528','阮明',7,'原来是这样，我还以为可以直接叠加备案。那办理备案需要企业的营业执照复印件吗？','yuán lái shì zhè yàng ， wǒ hái yǐ wéi kě yǐ zhí jiē dié jiā bèi àn 。 nà bàn lǐ bèi àn xū yào qǐ yè de yíng yè zhí zhào fù yìn jiàn ma ？','Ra là vậy, em cứ tưởng có thể đăng ký chồng lên trực tiếp. Vậy làm đăng ký có cần bản sao giấy phép kinh doanh của công ty không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_08','V528','老师',8,'需要的，而且必须是加盖企业公章的复印件，这是备案的核心材料，缺一不可。','xū yào de ， ér qiě bì xū shì jiā gài qǐ yè gōng zhāng de fù yìn jiàn ， zhè shì bèi àn de hé xīn cái liào ， quē yī bù kě 。','Cần chứ, mà phải là bản sao có đóng dấu công ty đàng hoàng, đây là giấy tờ cốt lõi của việc đăng ký, thiếu là không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_09','V528','阮明',9,'好，那我先跟企业对接好，把资质材料准备齐全，再来学校办理备案。','hǎo ， nà wǒ xiān gēn qǐ yè duì jiē hǎo ， bǎ zī zhì cái liào zhǔn bèi qí quán ， zài lái xué xiào bàn lǐ bèi àn 。','Vâng, vậy em sẽ trao đổi với công ty trước, chuẩn bị đầy đủ giấy tờ pháp lý rồi mới đến trường làm đăng ký ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT529','SV5','办理留学生校内勤工助学务工备案证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V529','SIT529','P1','suon_se','tuy_y',NULL,'留学生校内勤工助学同样有严格时长限制，校内备案仅学院留存，校外实习必须同步向出入境备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_01','V529','阮明',1,'老师，我申请了图书馆的校内助教兼职，这个需要办务工备案吗？','lǎo shī ， wǒ shēn qǐng le tú shū guǎn de xiào nèi zhù jiào jiān zhí ， zhè ge xū yào bàn wù gōng bèi àn ma ？','Thầy ơi, em xin được làm trợ giảng bán thời gian ở thư viện trong trường, cái này có cần đăng ký làm thêm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_02','V529','老师',2,'要的哦，校内勤工助学也得备案，系统里要有记录留存。','yào de ó ， xiào nèi qín gōng zhù xué yě dé bèi àn ， xì tǒng lǐ yào yǒu jì lù liú cún 。','Cần đó, làm thêm trong trường cũng phải đăng ký, hệ thống phải có lưu hồ sơ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_03','V529','阮明',3,'那打工时长还是和以前一样，一周最多二十小时对吧？','nà dǎ gōng shí cháng hái shì hé yǐ qián yī yàng ， yī zhōu zuì duō èr shí xiǎo shí duì ba ？','Vậy thời gian làm thêm vẫn như trước, một tuần tối đa hai mươi tiếng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_04','V529','老师',4,'平时上课周是二十小时上限，寒暑假可以放宽到四十小时。','píng shí shàng kè zhōu shì èr shí xiǎo shí shàng xiàn ， hán shǔ jià kě yǐ fàng kuān dào sì shí xiǎo shí 。','Bình thường trong tuần học thì giới hạn hai mươi tiếng, còn kỳ nghỉ đông hè thì được nới lên bốn mươi tiếng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_05','V529','阮明',5,'了解了。那这个备案办好之后，要不要拿去出入境更新签证信息呀？','liǎo jiě le 。 nà zhè ge bèi àn bàn hǎo zhī hòu ， yào bù yào ná qù chū rù jìng gēng xīn qiān zhèng xìn xī ya ？','Em hiểu rồi ạ. Vậy đăng ký xong rồi có cần mang ra xuất nhập cảnh cập nhật thông tin visa không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_06','V529','老师',6,'不用这么麻烦，校内兼职只需要学院内部存档，不用跑出入境。','bù yòng zhè me má fán ， xiào nèi jiān zhí zhǐ xū yào xué yuàn nèi bù cún dàng ， bù yòng pǎo chū rù jìng 。','Không cần rắc rối vậy đâu, làm thêm trong trường chỉ cần lưu hồ sơ nội bộ ở khoa thôi, không cần chạy ra xuất nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_07','V529','阮明',7,'行，那我把申请表填好，找您盖章备案就行。','xíng ， nà wǒ bǎ shēn qǐng biǎo tián hǎo ， zhǎo nín gài zhāng bèi àn jiù xíng 。','Dạ, vậy em điền đơn đăng ký xong sẽ tìm thầy để đóng dấu đăng ký ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT530','SV5','咨询逾期打工、超时务工对签证续签的影响',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V530','SIT530','P1','twist','chinh_thuc',NULL,'中国法律严格限制外籍留学生务工时长与务工范围，非法就业会直接影响居留续签，甚至限期离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_01','V530','阮明',1,'警官您好，我想咨询一下，如果留学生没有备案打工，或者打工超时，对签证续签有什么影响？','jǐng guān nín hǎo ， wǒ xiǎng zī xún yī xià ， rú guǒ liú xué shēng méi yǒu bèi àn dǎ gōng ， huò zhě dǎ gōng chāo shí ， duì qiān zhèng xù qiān yǒu shén me yǐng xiǎng ？','Chào anh công an, tôi muốn hỏi thăm một chút, nếu du học sinh làm thêm mà không đăng ký, hoặc làm thêm quá giờ quy định, thì sẽ ảnh hưởng thế nào đến việc gia hạn visa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_02','V530','辅警',2,'首次查到这类非法务工行为，会处以罚款，同时缩短半年的居留许可有效期。','shǒu cì chá dào zhè lèi fēi fǎ wù gōng háng wèi ， huì chǔ yǐ fá kuǎn ， tóng shí suō duǎn bàn nián de jū liú xǔ kě yǒu xiào qī 。','Nếu lần đầu bị phát hiện làm việc bất hợp pháp kiểu này, sẽ bị phạt tiền, đồng thời rút ngắn nửa năm thời hạn hiệu lực của giấy phép cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_03','V530','阮明',3,'只是缩短有效期吗？那如果是多次违规，会不会直接不给续签了？','zhǐ shì suō duǎn yǒu xiào qī ma ？ nà rú guǒ shì duō cì wéi guī ， huì bú huì zhí jiē bù gěi xù qiān le ？','Chỉ bị rút ngắn thời hạn thôi ạ? Vậy nếu vi phạm nhiều lần thì có bị từ chối gia hạn luôn không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_04','V530','辅警',4,'对的，两次及以上违规记录，出入境会直接驳回你的居留续签申请。','duì de ， liǎng cì jí yǐ shàng wéi guī jì lù ， chū rù jìng huì zhí jiē bó huí nǐ de jū liú xù qiān shēn qǐng 。','Đúng vậy, nếu có từ hai lần vi phạm trở lên, phòng xuất nhập cảnh sẽ trực tiếp từ chối đơn xin gia hạn cư trú của bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_05','V530','阮明',5,'那寒暑假的四十小时上限，超出一点点也算违规吗？','nà hán shǔ jià de sì shí xiǎo shí shàng xiàn ， chāo chū yì diǎn diǎn yě suàn wéi guī ma ？','Vậy giới hạn 40 giờ trong kỳ nghỉ đông hè, chỉ vượt quá một chút thôi cũng tính là vi phạm sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_06','V530','辅警',6,'算的，不管是学期还是假期，只要超出规定时长，一律判定为非法就业，没有例外。','suàn de ， bù guǎn shì xué qī hái shì jià qī ， zhǐ yào chāo chū guī dìng shí cháng ， yī lǜ pàn dìng wèi fēi fǎ jiù yè ， méi yǒu lì wài 。','Tính chứ, dù là trong học kỳ hay kỳ nghỉ, chỉ cần vượt quá thời gian quy định là đều bị coi là làm việc bất hợp pháp, không có ngoại lệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_07','V530','阮明',7,'啊这……那我要是换了实习单位，忘了注销之前的旧备案，会不会也有问题？','a zhè …… nà wǒ yào shì huàn le shí xí dān wèi ， wàng le zhù xiāo zhī qián de jiù bèi àn ， huì bú huì yě yǒu wèn tí ？','Ơ vậy à... Vậy nếu em đổi đơn vị thực tập mà quên hủy đăng ký cũ trước đó, thì có bị coi là có vấn đề không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_08','V530','辅警',8,'会的，系统会判定你同时在多家单位务工，同样属于违规行为。','huì de ， xì tǒng huì pàn dìng nǐ tóng shí zài duō jiā dān wèi wù gōng ， tóng yàng shǔ yú wéi guī xíng wéi 。','Có chứ, hệ thống sẽ xác định là bạn đang làm việc cùng lúc ở nhiều đơn vị, đó cũng là hành vi vi phạm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_09','V530','阮明',9,'明白了，我之后一定严格遵守时长规定，及时更新、注销实习备案，绝不违规。','míng bái le ， wǒ zhī hòu yí dìng yán gé zūn shǒu shí cháng guī dìng ， jí shí gēng xīn 、 zhù xiāo shí xí bèi àn ， jué bù wéi guī 。','Em hiểu rồi ạ, sau này em nhất định sẽ tuân thủ nghiêm ngặt quy định về thời gian, cập nhật và hủy đăng ký thực tập kịp thời, tuyệt đối không vi phạm nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT531','SV6','毕业申请短期停留签证（毕业生留华缓冲期）',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V531','SIT531','P1','suon_se','ban_chinh_thuc',NULL,'留学生毕业后可申请最长180天短期停留缓冲签证，该签证禁止任何形式务工、实习，到期必须离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_01','V531','阮明',1,'您好，我已经顺利毕业了，想申请毕业生的短期停留签证。','nín hǎo ， wǒ yǐ jīng shùn lì bì yè le ， xiǎng shēn qǐng bì yè shēng de duǎn qī tíng liú qiān zhèng 。','Chào anh chị, em đã tốt nghiệp thuận lợi rồi, giờ em muốn xin visa lưu trú ngắn hạn dành cho sinh viên mới tốt nghiệp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_02','V531','工作人员',2,'可以的，请准备好毕业证、离校证明、住宿登记单，还有一张证件照。','kě yǐ de ， qǐng zhǔn bèi hǎo bì yè zhèng 、 lí xiào zhèng míng 、 zhù sù dēng jì dān ， hái yǒu yī zhāng zhèng jiàn zhào 。','Được, bạn chuẩn bị bằng tốt nghiệp, giấy chứng nhận rời trường, phiếu đăng ký lưu trú, và một tấm ảnh thẻ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_03','V531','阮明',3,'好的。我想问下这个短期签证最长能办多久？是三十天还是更久？','hǎo de 。 wǒ xiǎng wèn xià zhè ge duǎn qī qiān zhèng zuì zhǎng néng bàn duō jiǔ ？ shì sān shí tiān hái shì gèng jiǔ ？','Dạ vâng. Em muốn hỏi visa ngắn hạn này có thể xin tối đa bao lâu ạ? Là 30 ngày hay lâu hơn?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_04','V531','工作人员',4,'毕业生缓冲居留最长可以申请一百八十天，你可以根据自己的需求选择时长。','bì yè shēng huǎn chōng jū liú zuì zhǎng kě yǐ shēn qǐng yì bǎi bā shí tiān ， nǐ kě yǐ gēn jù zì jǐ de xū qiú xuǎn zé shí cháng 。','Thời gian lưu trú đệm cho sinh viên mới tốt nghiệp tối đa có thể xin đến 180 ngày, bạn có thể chọn thời hạn theo nhu cầu của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_05','V531','阮明',5,'一百八十天这么久！那这段时间我能不能找实习、打工呢？','yì bǎi bā shí tiān zhè me jiǔ ！ nà zhè duàn shí jiān wǒ néng bù néng zhǎo shí xí 、 dǎ gōng ne ？','180 ngày lâu vậy sao! Vậy trong thời gian này em có thể tìm việc thực tập hoặc làm thêm được không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_06','V531','工作人员',6,'不可以的，毕业短期停留签证仅限旅游、整理行李、采购物品，禁止一切务工和实习行为。','bù kě yǐ de ， bì yè duǎn qī tíng liú qiān zhèng jǐn xiàn lǚ yóu 、 zhěng lǐ xíng lǐ 、 cǎi gòu wù pǐn ， jìn zhǐ yī qiè wù gōng hé shí xí xíng wéi 。','Không được đâu, visa lưu trú ngắn hạn sau tốt nghiệp chỉ dùng để du lịch, thu xếp hành lý, mua sắm đồ đạc, còn mọi hình thức làm thêm hay thực tập đều bị cấm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_07','V531','阮明',7,'懂了。那缓冲期到期之后，是不是完全不能延期，必须离境？','dǒng le 。 nà huǎn chōng qī dào qī zhī hòu ， shì bú shì wán quán bù néng yán qī ， bì xū lí jìng ？','Em hiểu rồi. Vậy sau khi hết thời gian đệm thì hoàn toàn không thể gia hạn, bắt buộc phải xuất cảnh đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_08','V531','工作人员',8,'是的，没有重大特殊事由，一律不予二次延期。','shì de ， méi yǒu zhòng dà tè shū shì yóu ， yī lǜ bù yǔ èr cì yán qī 。','Đúng vậy, nếu không có lý do đặc biệt quan trọng thì đều không được gia hạn lần hai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_09','V531','阮明',9,'好，我所有材料都备齐了，麻烦您帮我受理申请。','hǎo ， wǒ suǒ yǒu cái liào dōu bèi qí le ， má fán nín bāng wǒ shòu lǐ shēn qǐng 。','Dạ vâng, em đã chuẩn bị đầy đủ giấy tờ rồi, phiền anh chị giúp em tiếp nhận hồ sơ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT532','SV6','办理留学回国人员证明，用于境外学历认证',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V532','SIT532','P1','twist','ban_chinh_thuc',NULL,'留学回国人员证明是境外学历认证必备材料，需要完整留存全部在华居留、出入境记录，证件丢失需打印官方流水补充。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_01','V532','阮明',1,'老师，我马上毕业了，需要办留学回国人员证明，回国之后要做学历认证。','lǎo shī ， wǒ mǎ shàng bì yè le ， xū yào bàn liú xué huí guó rén yuán zhèng míng ， huí guó zhī hòu yào zuò xué lì rèn zhèng 。','Thầy ơi, em sắp tốt nghiệp rồi, em cần làm giấy chứng nhận du học sinh về nước, để về nước làm thủ tục công nhận văn bằng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_02','V532','老师',2,'没问题，你准备好护照签证页复印件、毕业证和毕业离校回执交给我。','méi wèn tí ， nǐ zhǔn bèi hǎo hù zhào qiān zhèng yè fù yìn jiàn 、 bì yè zhèng hé bì yè lí xiào huí zhí jiāo gěi wǒ 。','Không vấn đề gì, em chuẩn bị bản photo trang visa hộ chiếu, bằng tốt nghiệp và biên nhận rời trường sau khi tốt nghiệp rồi đưa cho thầy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_03','V532','阮明',3,'那个……我的旧护照之前剪角弄丢了，现在只有新护照的复印件，这样可以吗？','nà ge …… wǒ de jiù hù zhào zhī qián jiǎn jiǎo nòng diū le ， xiàn zài zhǐ yǒu xīn hù zhào de fù yìn jiàn ， zhè yàng kě yǐ ma ？','À... hộ chiếu cũ của em bị cắt góc với lại làm mất rồi ạ, giờ em chỉ có bản photo hộ chiếu mới thôi, như vậy có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_04','V532','老师',4,'这不行的，缺少完整的在华居留出入境记录，材料不齐全，我这边暂时没法给你开具证明。','zhè bù xíng de ， quē shǎo wán zhěng de zài huá jū liú chū rù jìng jì lù ， cái liào bù qí quán ， wǒ zhè biān zàn shí méi fǎ gěi nǐ kāi jù zhèng míng 。','Vậy thì không được đâu, thiếu đầy đủ hồ sơ xuất nhập cảnh và cư trú tại Trung Quốc, giấy tờ không đủ thì thầy tạm thời chưa thể cấp giấy chứng nhận cho em được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_05','V532','阮明',5,'啊？那怎么办？我实在找不回旧护照了。能不能去派出所或者大厅打印出入境记录代替？','a ？ nà zěn me bàn ？ wǒ shí zài zhǎo bù huí jiù hù zhào le 。 néng bù néng qù pài chū suǒ huò zhě dà tīng dǎ yìn chū rù jìng jì lù dài tì ？','Ơ? Vậy phải làm sao ạ? Em thật sự không tìm lại được hộ chiếu cũ nữa. Em có thể ra đồn công an hoặc trung tâm hành chính in lại hồ sơ xuất nhập cảnh để thay thế được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_06','V532','老师',6,'可以的，你去出入境大厅打印一份完整的出入境流水单，就能补上缺失的记录。','kě yǐ de ， nǐ qù chū rù jìng dà tīng dǎ yìn yī fèn wán zhěng de chū rù jìng liú shuǐ dān ， jiù néng bǔ shàng quē shī de jì lù 。','Được đó, em ra phòng xuất nhập cảnh in một bản sao kê xuất nhập cảnh đầy đủ, là có thể bổ sung được phần hồ sơ còn thiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_07','V532','阮明',7,'太好了，那我现在就去打印流水，补齐材料再来找您办理。','tài hǎo le ， nà wǒ xiàn zài jiù qù dǎ yìn liú shuǐ ， bǔ qí cái liào zài lái zhǎo nín bàn lǐ 。','Tuyệt quá, vậy em đi in sao kê ngay bây giờ, bổ sung đủ giấy tờ rồi quay lại tìm thầy làm thủ tục ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT533','SV6','退学终止学业，注销有效居留许可限期离境',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V533','SIT533','P1','that_bai_nhe','chinh_thuc',NULL,'退学学籍终止，学生居留许可注销，缓冲期仅用于收拾行李离境，缓冲到期无合法续签渠道，超期属于非法滞留。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_01','V533','阮明',1,'警官您好，我办理了退学手续，今天过来注销我的学生居留许可。','jǐng guān nín hǎo ， wǒ bàn lǐ le tuì xué shǒu xù ， jīn tiān guò lái zhù xiāo wǒ de xué shēng jū liú xǔ kě 。','Chào anh công an, tôi đã làm xong thủ tục thôi học, hôm nay đến để hủy giấy phép cư trú diện sinh viên của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_02','V533','民警',2,'出示一下你的退学离校证明。居留注销后，系统会自动给你三十天的合法停留缓冲期。','chū shì yī xià nǐ de tuì xué lí xiào zhèng míng 。 jū liú zhù xiāo hòu ， xì tǒng huì zì dòng gěi nǐ sān shí tiān de hé fǎ tíng liú huǎn chōng qī 。','Cho tôi xem giấy chứng nhận thôi học rời trường của anh chị. Sau khi hủy cư trú, hệ thống sẽ tự động cho anh chị 30 ngày lưu trú hợp pháp đệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_03','V533','阮明',3,'好的，证明在这里。那这三十天里，我正常出门旅游、出行都没问题吧？','hǎo de ， zhèng míng zài zhè lǐ 。 nà zhè sān shí tiān lǐ ， wǒ zhèng cháng chū mén lǚ yóu 、 chū xíng dōu méi wèn tí ba ？','Vâng, giấy chứng nhận đây ạ. Vậy trong 30 ngày này, tôi đi lại, du lịch bình thường thì không sao chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_04','V533','民警',4,'出行不受限制，但是你要清楚，缓冲期一到必须离境，没办法续签、延期。','chū xíng bù shòu xiàn zhì ， dàn shì nǐ yào qīng chǔ ， huǎn chōng qī yī dào bì xū lí jìng ， méi bàn fǎ xù qiān 、 yán qī 。','Việc đi lại không bị hạn chế, nhưng anh chị phải nhớ rõ, hết thời gian đệm là bắt buộc phải xuất cảnh, không thể gia hạn hay xin thêm thời gian được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_05','V533','阮明',5,'我明白。但我担心万一三十天内没买到机票，不小心超期停留了，会有什么处罚？','wǒ míng bái 。 dàn wǒ dān xīn wàn yī sān shí tiān nèi méi mǎi dào jī piào ， bù xiǎo xīn chāo qī tíng liú le ， huì yǒu shén me chǔ fá ？','Tôi hiểu rồi. Nhưng tôi lo là nếu trong 30 ngày không mua được vé máy bay, lỡ ở quá hạn thì sẽ bị xử phạt như thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_06','V533','民警',6,'退学后你已经没有有效学籍了，一旦超期停留，每天都会产生罚款，还会留下不良入境记录，影响以后来华。','tuì xué hòu nǐ yǐ jīng méi yǒu yǒu xiào xué jí le ， yí dàn chāo qī tíng liú ， měi tiān dōu huì chǎn shēng fá kuǎn ， hái huì liú xià bù liáng rù jìng jì lù ， yǐng xiǎng yǐ hòu lái huá 。','Sau khi thôi học thì anh chị không còn tư cách học sinh hợp lệ nữa, nếu ở quá hạn thì mỗi ngày đều sẽ bị tính phạt, còn để lại tiền sử xuất nhập cảnh xấu, ảnh hưởng đến việc quay lại Trung Quốc sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_07','V533','阮明',7,'这么严重……那我再确认下，缓冲期内如果我临时回国一趟，还能再进来吗？','zhè me yán zhòng …… nà wǒ zài què rèn xià ， huǎn chōng qī nèi rú guǒ wǒ lín shí huí guó yī tàng ， hái néng zài jìn lái ma ？','Nghiêm trọng vậy sao... Vậy tôi xác nhận lại, trong thời gian đệm nếu tôi về nước tạm thời một chuyến, thì có thể quay lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_08','V533','民警',8,'不能，居留注销后签证直接失效，一旦离境，就无法再次入境中国了。','bù néng ， jū liú zhù xiāo hòu qiān zhèng zhí jiē shī xiào ， yí dàn lí jìng ， jiù wú fǎ zài cì rù jìng zhōng guó le 。','Không được, sau khi hủy cư trú thì visa mất hiệu lực ngay, một khi đã xuất cảnh là không thể nhập cảnh lại Trung Quốc được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_09','V533','阮明',9,'我清楚规定了，我会在三十天内订好机票，按时回国，绝不逾期。','wǒ qīng chǔ guī dìng le ， wǒ huì zài sān shí tiān nèi dìng hǎo jī piào ， àn shí huí guó ， jué bù yú qī 。','Tôi đã hiểu rõ quy định rồi, tôi sẽ đặt vé máy bay trong vòng 30 ngày, về nước đúng hạn, tuyệt đối không để quá hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT534','SV6','签证到期前彻底回国，咨询居留注销流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V534','SIT534','P1','suon_se','tuy_y',NULL,'留学生永久离境建议主动注销居留许可，证件到期自动失效虽无罚款，但会提升下次来华签证的审核严格程度。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_01','V534','阮明',1,'警官，我毕业之后就直接回国了，以后暂时不来中国了，需要注销居留吗？','jǐng guān ， wǒ bì yè zhī hòu jiù zhí jiē huí guó le ， yǐ hòu zàn shí bù lái zhōng guó le ， xū yào zhù xiāo jū liú ma ？','Anh công an ơi, em tốt nghiệp xong là về nước luôn, sau này tạm thời không sang Trung Quốc nữa, vậy em có cần hủy cư trú không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_02','V534','辅警',2,'建议主动注销哈，长期离境不注销，休眠证件容易产生异常记录。','jiàn yì zhǔ dòng zhù xiāo hā ， cháng qī lí jìng bù zhù xiāo ， xiū mián zhèng jiàn róng yì chǎn shēng yì cháng jì lù 。','Nên chủ động hủy đi nha, để lâu mà không hủy, giấy tờ ở trạng thái treo dễ phát sinh ghi nhận bất thường lắm.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_03','V534','阮明',3,'哦，那如果我不主动注销，让它到期自动失效，会不会有负面影响？','ó ， nà rú guǒ wǒ bù zhǔ dòng zhù xiāo ， ràng tā dào qī zì dòng shī xiào ， huì bú huì yǒu fù miàn yǐng xiǎng ？','À, vậy nếu em không chủ động hủy, cứ để nó tự hết hạn thì có ảnh hưởng gì xấu không ạ?','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_04','V534','辅警',4,'到期自动失效是没有罚款的，但是下次你想申请来华签证，审核会更严格、更麻烦。','dào qī zì dòng shī xiào shì méi yǒu fá kuǎn de ， dàn shì xià cì nǐ xiǎng shēn qǐng lái huá qiān zhèng ， shěn hé huì gèng yán gé 、 gèng má fán 。','Tự hết hạn thì không bị phạt tiền đâu, nhưng lần sau em muốn xin visa sang Trung Quốc lại thì việc xét duyệt sẽ gắt gao và phiền phức hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_05','V534','阮明',5,'原来是这样。那注销的话，只带护照就够了吗？','yuán lái shì zhè yàng 。 nà zhù xiāo de huà ， zhǐ dài hù zhào jiù gòu le ma ？','Ra là vậy. Vậy nếu hủy thì chỉ cần mang hộ chiếu thôi là đủ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_06','V534','辅警',6,'还要带上你的毕业证，现场办理注销，当场就能给你打印注销回执。','hái yào dài shàng nǐ de bì yè zhèng ， xiàn chǎng bàn lǐ zhù xiāo ， dāng chǎng jiù néng gěi nǐ dǎ yìn zhù xiāo huí zhí 。','Còn phải mang theo bằng tốt nghiệp nữa, làm thủ tục hủy tại chỗ luôn, xong là in biên nhận hủy cho em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_07','V534','阮明',7,'那我保留好这个回执，以后再来留学办签证会顺利一点？','nà wǒ bǎo liú hǎo zhè ge huí zhí ， yǐ hòu zài lái liú xué bàn qiān zhèng huì shùn lì yì diǎn ？','Vậy em giữ kỹ cái biên nhận này, sau này quay lại du học xin visa sẽ thuận lợi hơn đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_08','V534','辅警',8,'对的，有完整的注销记录，签证审核通过率会高很多。','duì de ， yǒu wán zhěng de zhù xiāo jì lù ， qiān zhèng shěn hé tōng guò lǜ huì gāo hěn duō 。','Đúng rồi, có hồ sơ hủy đầy đủ thì tỷ lệ xét duyệt visa đậu sẽ cao hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_09','V534','阮明',9,'行，那我离校前抽空过来把居留注销了。','xíng ， nà wǒ lí xiào qián chōu kòng guò lái bǎ jū liú zhù xiāo le 。','Được ạ, vậy trước khi rời trường em sẽ tranh thủ qua đây hủy cư trú luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT535','SV6','毕业短期签证到期无法按时离境，申请延期缓冲',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V535','SIT535','P1','twist','chinh_thuc',NULL,'毕业生短期缓冲签证一般不可延期，仅航班取消、重病住院等不可抗力可短期延长停留期限，且需缴纳签证工本费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_01','V535','阮明',1,'您好，我的毕业短期停留签证马上到期了，但是我的回国航班延误取消了，实在没办法按时离境，想申请延期。','nín hǎo ， wǒ de bì yè duǎn qī tíng liú qiān zhèng mǎ shàng dào qī le ， dàn shì wǒ de huí guó háng bān yán wù qǔ xiāo le ， shí zài méi bàn fǎ àn shí lí jìng ， xiǎng shēn qǐng yán qī 。','Chào anh chị, visa lưu trú ngắn hạn sau tốt nghiệp của tôi sắp hết hạn rồi, nhưng chuyến bay về nước của tôi bị hoãn rồi hủy, thực sự không thể xuất cảnh đúng hạn được, tôi muốn xin gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_02','V535','工作人员',2,'我先说明一下政策，毕业短期签证原则上是不允许延期的，只有突发客观情况才能特殊审批。','wǒ xiān shuō míng yī xià zhèng cè ， bì yè duǎn qī qiān zhèng yuán zé shàng shì bù yǔn xǔ yán qī de ， zhǐ yǒu tū fā kè guān qíng kuàng cái néng tè shū shěn pī 。','Tôi giải thích trước về quy định, visa ngắn hạn sau tốt nghiệp về nguyên tắc là không được gia hạn, chỉ có trường hợp phát sinh khách quan đột xuất mới được xét duyệt đặc biệt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_03','V535','阮明',3,'我理解！这次是大规模国际航班取消，航空公司已经给我开了延误证明，您看一下。','wǒ lǐ jiě ！ zhè cì shì dà guī mó guó jì háng bān qǔ xiāo ， háng kōng gōng sī yǐ jīng gěi wǒ kāi le yán wù zhèng míng ， nín kàn yī xià 。','Tôi hiểu ạ! Lần này là do hủy hàng loạt chuyến bay quốc tế, hãng hàng không đã cấp cho tôi giấy chứng nhận hoãn chuyến rồi, anh chị xem qua giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_04','V535','工作人员',4,'嗯，航班延误属于不可抗力，符合特殊审批条件，最多可以给你延期十五天。','ń ， háng bān yán wù shǔ yú bù kě kàng lì ， fú hé tè shū shěn pī tiáo jiàn ， zuì duō kě yǐ gěi nǐ yán qī shí wǔ tiān 。','Ừm, việc hoãn chuyến bay thuộc trường hợp bất khả kháng, đủ điều kiện xét duyệt đặc biệt, tối đa có thể gia hạn cho anh chị 15 ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_05','V535','阮明',5,'太好了，太感谢了！那这十五天的延期需要交手续费吗？','tài hǎo le ， tài gǎn xiè le ！ nà zhè shí wǔ tiān de yán qī xū yào jiāo shǒu xù fèi ma ？','Tuyệt quá, cảm ơn anh chị nhiều lắm! Vậy gia hạn 15 ngày này có cần đóng phí thủ tục không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_06','V535','工作人员',6,'需要收取标准的签证工本费，没有免费办理的政策。','xū yào shōu qǔ biāo zhǔn de qiān zhèng gōng běn fèi ， méi yǒu miǎn fèi bàn lǐ de zhèng cè 。','Cần đóng phí làm visa theo mức quy định, không có chính sách miễn phí đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_07','V535','阮明',7,'明白。那我是不是递交延误证明、护照和证件照就可以办理？','míng bái 。 nà wǒ shì bú shì dì jiāo yán wù zhèng míng 、 hù zhào hé zhèng jiàn zhào jiù kě yǐ bàn lǐ ？','Tôi hiểu rồi. Vậy tôi chỉ cần nộp giấy chứng nhận hoãn chuyến, hộ chiếu và ảnh thẻ là có thể làm thủ tục được đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_08','V535','工作人员',8,'材料齐全的话，三个工作日就能完成审批和制证。','cái liào qí quán de huà ， sān gè gōng zuò rì jiù néng wán chéng shěn pī hé zhì zhèng 。','Nếu giấy tờ đầy đủ thì trong ba ngày làm việc là có thể hoàn tất xét duyệt và làm giấy tờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_09','V535','阮明',9,'好，材料我都带齐了，现在递交我的延期申请。','hǎo ， cái liào wǒ dōu dài qí le ， xiàn zài dì jiāo wǒ de yán qī shēn qǐng 。','Vâng, giấy tờ tôi đã mang đầy đủ rồi, giờ tôi xin nộp đơn xin gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT601','SF1','下载注册国际通用视频软件，和父母跨国视频通话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V601','SIT601','P1','suon_se','tuy_y',NULL,'国内本土社交软件海外受限，留学生普遍使用国际通用通讯软件和境外家人联络。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_01','V601','阮明',1,'小林，我想装一款国外能用的视频软件跟爸妈通话，你知道哪款好用吗？','xiǎo lín， wǒ xiǎng zhuāng yī kuǎn guó wài néng yòng de shì pín ruǎn jiàn gēn bà mā tōng huà， nǐ zhī dào nǎ kuǎn hǎo yòng ma？','Tiểu Lâm, tớ muốn cài một app video dùng được ở nước ngoài để gọi cho bố mẹ, cậu biết app nào dùng ổn không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_02','V601','小林',2,'这款APP国内外都能互通，下载之后用邮箱注册就行啦。','zhè kuǎn APP guó nèi wài dōu néng hù tōng， xià zài zhī hòu yòng yóu xiāng zhù cè jiù xíng la。','App này trong nước ngoài nước gì cũng liên lạc được hết, tải về rồi đăng ký bằng email là xong ngay ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_03','V601','阮明',3,'国内手机号注册的话，越南那边收得到验证码吗？','guó nèi shǒu jī hào zhù cè de huà， yuè nán nà biān shōu dé dào yàn zhèng mǎ ma？','Nếu đăng ký bằng số điện thoại trong nước thì bên Việt Nam có nhận được mã xác nhận không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_04','V601','小林',4,'手机号跨国有延迟，直接绑定邮箱登录最稳妥呢。','shǒu jī hào kuà guó yǒu yán chí， zhí jiē bǎng dìng yóu xiāng dēng lù zuì wěn tuǒ ne。','Số điện thoại xuyên quốc gia hay bị trễ lắm, cứ gắn email để đăng nhập là chắc ăn nhất đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_05','V601','阮明',5,'注册完成后，直接搜索爸妈的账号就能发起视频吗？','zhù cè wán chéng hòu， zhí jiē sōu suǒ bà mā de zhàng hào jiù néng fā qǐ shì pín ma？','Đăng ký xong là tớ tìm tài khoản của bố mẹ rồi gọi video luôn được hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_06','V601','小林',6,'没错，还能发照片、短视频，日常报平安很方便。','méi cuò， hái néng fā zhào piān、 duǎn shì pín， rì cháng bào píng ān hěn fāng biàn。','Đúng rồi, còn gửi ảnh, gửi video ngắn được nữa, báo bình an hằng ngày tiện lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_07','V601','阮明',7,'太好了，你教我一步步注册，今晚就能跟家里视频。','tài hǎo le， nǐ jiāo wǒ yí bù bù zhù cè， jīn wǎn jiù néng gēn jiā lǐ shì pín。','Tuyệt quá, cậu chỉ tớ đăng ký từng bước đi, tối nay là gọi video về nhà được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT602','SF1','宿舍WiFi卡顿，求助室友调试网络方便和家人打电话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V602','SIT602','P1','twist','tuy_y',NULL,'高校宿舍晚八点至十点是网络使用高峰，多人同时联网会造成网速变慢、跨国视频卡顿。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_01','V602','阮明',1,'我一打开视频软件网络就卡顿，根本没法跟爸妈正常通话啊。','wǒ yī dǎ kāi shì pín ruǎn jiàn wǎng luò jiù kǎ dùn， gēn běn méi fǎ gēn bà mā zhèng cháng tōng huà a。','Tớ vừa mở app video lên là mạng bị giật lag ngay, chẳng nói chuyện được với bố mẹ gì cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_02','V602','小林',2,'是不是宿舍同时好几个人连WiFi，带宽被占满了？','shì bú shì sù shè tóng shí hǎo jǐ gè rén lián WiFi， dài kuān bèi zhàn mǎn le？','Có phải cùng lúc mấy người trong phòng đều nối WiFi nên băng thông bị chiếm hết không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_03','V602','阮明',3,'刚才隔壁宿舍也在刷视频，我切换手机流量试试还是卡嘛。','gāng cái gé bì sù shè yě zài shuā shì pín， wǒ qiè huàn shǒu jī liú liàng shì shì hái shì kǎ ma。','Lúc nãy phòng bên cạnh cũng đang xem video, tớ thử chuyển sang 4G rồi vẫn giật lag chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_04','V602','小林',4,'我教你断开自动连接的多余设备，路由器重启一下会流畅很多。','wǒ jiāo nǐ duàn kāi zì dòng lián jiē de duō yú shè bèi， lù yóu qì zhòng qǐ yī xià huì liú chàng hěn duō。','Để tớ chỉ cậu ngắt bớt mấy thiết bị tự động kết nối thừa, khởi động lại router là mượt hơn nhiều đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_05','V602','阮明',5,'重启路由器之后，跨国视频延迟能降低多少？','chóng qǐ lù yóu qì zhī hòu， kuà guó shì pín yán chí néng jiàng dī duō shǎo？','Khởi động lại router xong thì độ trễ gọi video xuyên quốc gia giảm được bao nhiêu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_06','V602','小林',6,'至少少一半卡顿，避开晚间八点上网高峰效果更好。','zhì shǎo shǎo yí bàn kǎ dùn， bì kāi wǎn jiān bā diǎn shàng wǎng gāo fēng xiào guǒ gèng hǎo。','Giảm ít nhất một nửa độ giật, tránh giờ cao điểm tầm tám giờ tối thì càng mượt hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_07','V602','阮明',7,'我现在跟着你的步骤操作，等下再打视频电话。','wǒ xiàn zài gēn zhe nǐ de bù zhòu cāo zuò， děng xià zài dǎ shì pín diàn huà。','Giờ tớ làm theo các bước cậu chỉ đây, lát nữa gọi video lại thử xem sao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT603','SF1','时差冲突，错过和父母固定视频时间，重新约定时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V603','SIT603','P1','suon_se','tuy_y',NULL,'跨国跨时区留学生和家人一般会约定固定通话时间，临时无法上线必须提前留言报平安，避免家人过度担忧。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_01','V603','阮明',1,'昨天上课拖堂，错过了和爸妈约定的视频时间，他们一直等我。','zuó tiān shàng kè tuō táng， cuò guò le hé bà mā yuē dìng de shì pín shí jiān， tā men yì zhí děng wǒ。','Hôm qua lớp học kéo dài hơn dự kiến, tớ lỡ mất giờ video hẹn với bố mẹ, ông bà cứ chờ mãi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_02','V603','苏雯',2,'越南和国内有一小时时差，你可以提前调整固定联络时段哦。','yuè nán hé guó nèi yǒu yī xiǎo shí shí chà， nǐ kě yǐ tí qián tiáo zhěng gù dìng lián luò shí duàn ó。','Việt Nam với trong nước lệch nhau một tiếng, cậu nên chủ động điều chỉnh trước khung giờ liên lạc cố định đó nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_03','V603','阮明',3,'我这边晚上七点，越南就是傍晚六点，这个时间他们刚好下班。','wǒ zhè biān wǎn shàng qī diǎn， yuè nán jiù shì bàng wǎn liù diǎn， zhè ge shí jiān tā men gāng hǎo xià bān。','Bên tớ bảy giờ tối thì bên Việt Nam là sáu giờ chiều, đúng lúc bố mẹ vừa tan làm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_04','V603','苏雯',4,'那你跟家里重新敲定这个时间，提前发消息提醒他们上线吧。','nà nǐ gēn jiā lǐ chóng xīn qiāo dìng zhè ge shí jiān， tí qián fā xiāo xī tí xǐng tā men shàng xiàn ba。','Vậy cậu chốt lại khung giờ này với nhà mình đi, rồi nhắn tin nhắc trước để họ lên mạng đúng giờ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_05','V603','阮明',5,'我昨天临时缺场，爸妈还以为我出了什么事，特别担心。','wǒ zuó tiān lín shí quē chǎng， bà mā hái yǐ wéi wǒ chū le shén me shì， tè bié dān xīn。','Hôm qua tớ tự dưng vắng mặt, bố mẹ cứ tưởng tớ gặp chuyện gì, lo lắng lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_06','V603','苏雯',6,'下次如果有课，提前发文字留言告知家人，免得他们焦虑。','xià cì rú guǒ yǒu kè， tí qián fā wén zì liú yán gào zhī jiā rén， miǎn de tā men jiāo lǜ。','Lần sau nếu có tiết học thì nhắn tin báo trước cho gia đình, kẻo họ lo lắng không cần thiết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_07','V603','阮明',7,'我记下了，今晚提前跟家里敲定新的视频时段。','wǒ jì xià le， jīn wǎn tí qián gēn jiā lǐ qiāo dìng xīn de shì pín shí duàn。','Tớ ghi nhớ rồi, tối nay sẽ chốt lại giờ video mới với gia đình sớm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT604','SF1','软件登录失败、账号被锁，找同学帮忙找回账号',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V604','SIT604','P1','that_bai_nhe','tuy_y',NULL,'公共网络存在安全风险，跨国通讯软件检测到异地登录会自动锁号，保护用户隐私与账号安全。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_01','V604','阮明',1,'糟糕，我的视频软件账号提示异常登录，直接被系统锁住了。','zāo gāo， wǒ de shì pín ruǎn jiàn zhàng hào tí shì yì cháng dēng lù， zhí jiē bèi xì tǒng suǒ zhù le。','Chết rồi, tài khoản app video của tớ báo đăng nhập bất thường, bị hệ thống khóa luôn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_02','V604','小林',2,'你是不是切换手机、频繁换WiFi登录，系统判定有风险？','nǐ shì bú shì qiè huàn shǒu jī、 pín fán huàn WiFi dēng lù， xì tǒng pàn dìng yǒu fēng xiǎn？','Có phải cậu đổi điện thoại, đổi WiFi liên tục nên hệ thống nghi ngờ rủi ro không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_03','V604','阮明',3,'昨天去图书馆连公共网络登录过，之后回家就登不上去嘛。','zuó tiān qù tú shū guǎn lián gōng gòng wǎng luò dēng lù guò， zhī hòu huí jiā jiù dēng bù shàng qù ma。','Hôm qua tớ ra thư viện đăng nhập bằng mạng công cộng, xong về nhà là không vào được nữa chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_04','V604','小林',4,'解锁需要邮箱收验证链接，你注册时绑定的邮箱还能正常使用吗？','jiě suǒ xū yào yóu xiāng shōu yàn zhèng liàn jiē， nǐ zhù cè shí bǎng dìng de yóu xiāng hái néng zhèng cháng shǐ yòng ma？','Mở khóa cần nhận link xác nhận qua email, cái email cậu gắn lúc đăng ký còn dùng được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_05','V604','阮明',5,'邮箱密码我记混了，现在双重验证全部卡住没法操作。','yóu xiāng mì mǎ wǒ jì hùn le， xiàn zài shuāng chóng yàn zhèng quán bù kǎ zhù méi fǎ cāo zuò。','Tớ nhớ nhầm mật khẩu email rồi, giờ xác thực hai lớp bị kẹt luôn không thao tác được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_06','V604','小林',6,'只能先找回邮箱密码，才能解锁通讯软件账号，一步一步来。','zhǐ néng xiān zhǎo huí yóu xiāng mì mǎ， cái néng jiě suǒ tōng xùn ruǎn jiàn zhàng hào， yí bù yí bù lái。','Vậy chỉ còn cách lấy lại mật khẩu email trước, mới mở khóa được tài khoản app gọi video, từ từ làm từng bước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_07','V604','阮明',7,'麻烦你陪我操作，不然我今天完全联系不上家里人。','má fán nǐ péi wǒ cāo zuò， bù rán wǒ jīn tiān wán quán lián xì bù shàng jiā lǐ rén。','Phiền cậu ngồi làm cùng tớ với, không thì hôm nay tớ chịu, không liên lạc được với gia đình luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT605','SF1','不会操作美颜、屏幕共享，请教室友教自己给家人展示校园',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V605','SIT605','P1','suon_se','tuy_y',NULL,'国际视频软件自带基础美颜、屏幕共享功能，留学生常用来实时展示校园、宿舍生活给海外亲人。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_01','V605','阮明',1,'我想给爸妈看看校园风景，不知道怎么打开屏幕共享功能啊。','wǒ xiǎng gěi bà mā kàn kàn xiào yuán fēng jǐng， bù zhī dào zěn me dǎ kāi píng mù gòng xiǎng gōng néng a。','Tớ muốn cho bố mẹ xem cảnh trường, mà không biết mở tính năng chia sẻ màn hình kiểu gì cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_02','V605','小林',2,'视频通话界面下方有分享按钮，点一下就能同步实景画面呢。','shì pín tōng huà jiè miàn xià fāng yǒu fēn xiǎng àn niǔ， diǎn yī xià jiù néng tóng bù shí jǐng huà miàn ne。','Giao diện gọi video có nút chia sẻ ở phía dưới ấy, bấm vào là hình ảnh thực tế đồng bộ ngay.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_03','V605','阮明',3,'另外画面光线不好，有没有简单的美颜提亮功能？','lìng wài huà miàn guāng xiàn bù hǎo， yǒu méi yǒu jiǎn dān de měi yán tí liàng gōng néng？','Với lại ánh sáng trong hình không đẹp lắm, có tính năng làm đẹp làm sáng đơn giản nào không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_04','V605','小林',4,'侧边工具栏有基础提亮滤镜，不用复杂调整，一键开启就行。','cè biān gōng jù lán yǒu jī chǔ tí liàng lǜ jìng， bù yòng fù zá tiáo zhěng， yī jiàn kāi qǐ jiù xíng。','Ở thanh công cụ bên cạnh có bộ lọc làm sáng cơ bản, không cần chỉnh phức tạp, bật một cái là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_05','V605','阮明',5,'共享画面的时候，手机里的照片相册也能同步展示给家人吗？','gòng xiǎng huà miàn de shí hòu， shǒu jī lǐ de zhào piān xiàng cè yě néng tóng bù zhǎn shì gěi jiā rén ma？','Lúc chia sẻ màn hình vậy thì album ảnh trong điện thoại có đồng bộ hiện cho gia đình xem được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_06','V605','小林',6,'可以，共享时切换相册，宿舍、教学楼照片都能直接看。','kě yǐ， gòng xiǎng shí qiè huàn xiàng cè， sù shè、 jiào xué lóu zhào piān dōu néng zhí jiē kàn。','Được chứ, lúc chia sẻ chuyển sang album là ảnh ký túc xá, giảng đường gì cũng xem trực tiếp được hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_07','V605','阮明',7,'太实用了，今晚视频带爸妈逛一遍我们整个校园。','tài shí yòng le， jīn wǎn shì pín dài bà mā guàng yī biàn wǒ men zhěng gè xiào yuán。','Hay quá, tối nay tớ sẽ gọi video dẫn bố mẹ đi một vòng khắp trường luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT606','SF1','境外手机号收不到软件验证码，改用邮箱登录联系家人',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V606','SIT606','P1','twist','ban_chinh_thuc',NULL,'境内外运营商短信互通存在延迟、丢失问题，跨国软件优先推荐邮箱作为备用验证渠道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_01','V606','阮明',1,'我更换新手机，软件登录要验证码，越南手机号一直收不到短信。','wǒ gēng huàn xīn shǒu jī， ruǎn jiàn dēng lù yào yàn zhèng mǎ， yuè nán shǒu jī hào yì zhí shōu bú dào duǎn xìn。','Tôi đổi điện thoại mới, app yêu cầu nhập mã xác nhận để đăng nhập, mà số điện thoại Việt Nam mãi không nhận được tin nhắn.',NULL) ON CONFLICT DO NOTHING;
